//! 🧪️ The actual installed producer publishes its native cursor and reply before interruption.
use semio_framework_value_factory::*;
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use std::sync::{Arc,atomic::{AtomicUsize,AtomicBool,Ordering}};
#[derive(FactoryPayloadRetirement)]
#[value(crate="semio_framework_value_factory")]
struct Producer{#[factory_owned]calls:AtomicUsize,#[factory_owned]recoveries:AtomicUsize,#[factory_owned]interrupt:AtomicBool,#[factory_owned]pointer:AtomicUsize}
impl ArtifactOwnedValueRetirementFactory<String> for Producer{
 fn retirement_birth_bytes(&self,value:&String)->usize{ArtifactOwnedValueRetirementFactory::retirement_birth_bytes(&OwnedValueRetirementFactory::<String>::default(),value)}
 fn retire_owned_work_demand(&self,value:&String)->Result<u64,ValueError>{OwnedValueRetirementFactory::<String>::default().retire_owned_work_demand(value)}
 fn retire_owned_demands(&self,value:&String)->Result<RetirementDemand,ValueError>{OwnedValueRetirementFactory::<String>::default().retire_owned_demands(value)}
 fn retire_owned<'reply>(&self,value:&mut Option<String>,effect:&mut RetainedAllocationEffect<'_>,reply:FactoryProducerReply<'reply,dyn ErasedSnapshotRetirement,OriginalRetirementFailure>)->FactoryProducerReplyComplete<'reply,OriginalRetirementFailure>{self.calls.fetch_add(1,Ordering::SeqCst);assert_eq!(value.as_ref().unwrap().as_ptr()as usize,self.pointer.load(Ordering::SeqCst));let complete=OwnedValueRetirementFactory::<String>::default().retire_owned(value,effect,reply);if self.interrupt.swap(false,Ordering::SeqCst){panic!("actual factory recorded its reply before interruption")}complete}
 fn recover_retire_owned<'reply>(&self,_:&mut Option<String>,_:&mut RetainedAllocationEffect<'_>,reply:FactoryProducerReply<'reply,dyn ErasedSnapshotRetirement,OriginalRetirementFailure>)->FactoryProducerReplyComplete<'reply,OriginalRetirementFailure>{self.recoveries.fetch_add(1,Ordering::SeqCst);reply.pending()}
}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn complete<T,E>(poll:RetainedWorkPoll<T,E>)->RetainedWorkOutcome<T,E>{match poll{RetainedWorkPoll::Complete(turn)=>turn,RetainedWorkPoll::Pending{..}=>panic!("fixture expected a recorded completed reply")}}
fn drain(owner:&mut dyn ErasedSnapshotRetirement,bank:&mut EffectBank){for _ in 0..512{if owner.terminal_is_empty(){return}let d=owner.next_demand(65536).unwrap();let g=grant(d);let work=owner.next_computational_work(65536).unwrap();let((turn,actual),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run(g,work,|effect|owner.close_step(effect)));let turn=complete(turn);let p=turn.result.unwrap().progress();assert_eq!(actual.unwrap_or(0),p.retained_capacity_bytes);bank.post(p,g,heap);assert_eq!(bank.take_admitted(),Some(true));}panic!("finite factory fixture failed to close")}
#[test]
fn resident_factory_owner_and_recorded_reply_survive_unwind_without_replay(){borrowed_factory_reply_and_original_issuer_survive_unwind_on_the_same_bank();}

#[test]
fn actual_source_funds_pair_transfer_into_resident_outputs(){
 let law:serde_json::Value=serde_json::from_str(include_str!("pair.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("pair.schema.json")).unwrap();for(k,v)in law.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v)}
 let mut bank=EffectBank::new(Wallet::from_profile(&serde_json::from_str::<serde_json::Value>(include_str!("fixture.json")).unwrap()["stock"]));
 let((value,issuer),held)=semio_framework_value_testing_allocator::observe_retirement_allocations(||(law["body"].as_str().unwrap().to_owned(),Arc::new(OwnedValueRetirementFactory::<String>::default())));
 let held_grant=bank.loan(1,4096);bank.post(RetainedCloneProgress{retained_capacity_bytes:held.0,..Default::default()},held_grant,held);
 let pointer=value.as_ptr();let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=issuer;let address=Arc::as_ptr(&factory)as*const()as usize;let mut owner=owned::FactoryOwnedSourceAuthority::new(value,factory);let mut output=None;let mut returned=None;
 let d=owned::FactoryOwnedSourceAuthority::<String>::transfer_original_demand();assert!(d.copy_bytes<=law["maximumCopyBytes"].as_u64().unwrap()as usize);let g=grant(d);
 for axis in 0..4{let mut denied=g;let units=if axis==3{0}else{1};match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes-=1,2=>denied.maximum_depth=0,_=>{}}let mut reply=None;
  let((poll,_),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run_with_source(denied,units,|effect,_|{let before=effect.performed_work();drop(owner.transfer_original_into(&mut output,&mut returned,effect,semio_framework_value_control_contract::OriginalEffectReply::borrow(&mut reply).unwrap()).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})}));
  assert_eq!(poll.work(),0);assert_eq!(heap,(0,0));let step=reply.take().unwrap().unwrap();assert_eq!(step.progress(),RetainedCloneProgress::default());bank.take_admitted();bank.post(step.progress(),denied,heap);assert!(output.is_none()&&returned.is_none());assert_eq!(owner.get().as_ptr(),pointer);
 }
 let mut reply=None;let((poll,_),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run_with_source(g,1,|effect,_|{let before=effect.performed_work();drop(owner.transfer_original_into(&mut output,&mut returned,effect,semio_framework_value_control_contract::OriginalEffectReply::borrow(&mut reply).unwrap()).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})}));assert_eq!(poll.work(),1);assert_eq!(bank.take_admitted(),Some(true));let step=reply.take().unwrap().unwrap();bank.post(step.progress(),g,heap);assert!(owner.terminal_is_empty());assert_eq!(output.as_ref().unwrap().as_ptr(),pointer);assert_eq!(output.as_deref(),Some(law["body"].as_str().unwrap()));assert_eq!(Arc::as_ptr(returned.as_ref().unwrap())as*const()as usize,address);
 let mut retirement=None;let g=grant(owned::FactoryOwnedRetirement::<String>::original_admission_demands(&output));let mut reply=None;let((poll,_),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run(g,1,|effect|{let before=effect.performed_work();drop(owned::FactoryOwnedRetirement::admit_original_into(&mut output,&mut returned,&mut retirement,effect,semio_framework_value_control_contract::OriginalEffectReply::borrow(&mut reply).unwrap()).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})}));assert_eq!(poll.work(),1);assert_eq!(bank.take_admitted(),Some(true));bank.post(reply.take().unwrap().unwrap().progress(),g,heap);retire_transferred_pair(&mut retirement,&mut bank);assert!(retirement.is_none());
}

#[derive(FactoryPayloadRetirement)]
#[value(crate="semio_framework_value_factory")]
struct BorrowedProbe{#[factory_owned]calls:AtomicUsize,#[factory_owned]recoveries:AtomicUsize,#[factory_owned]interrupt:AtomicBool,#[factory_owned]pointer:AtomicUsize,#[factory_owned]allocated:AtomicUsize,#[factory_owned]released:AtomicUsize}
impl ArtifactOwnedValueRetirementFactory<String> for BorrowedProbe{
 fn retirement_birth_bytes(&self,value:&String)->usize{OwnedValueRetirementFactory::<String>::default().retirement_birth_bytes(value)}
 fn retire_owned_work_demand(&self,value:&String)->Result<u64,ValueError>{OwnedValueRetirementFactory::<String>::default().retire_owned_work_demand(value)}
 fn retire_owned_demands(&self,value:&String)->Result<RetirementDemand,ValueError>{OwnedValueRetirementFactory::<String>::default().retire_owned_demands(value)}
 fn retire_owned<'reply>(&self,value:&mut Option<String>,effect:&mut RetainedAllocationEffect<'_>,reply:FactoryProducerReply<'reply,dyn ErasedSnapshotRetirement,OriginalRetirementFailure>)->FactoryProducerReplyComplete<'reply,OriginalRetirementFailure>{self.calls.fetch_add(1,Ordering::SeqCst);assert_eq!(value.as_ref().unwrap().as_ptr()as usize,self.pointer.load(Ordering::SeqCst));let(result,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||OwnedValueRetirementFactory::<String>::default().retire_owned(value,effect,reply));self.allocated.store(heap.0,Ordering::SeqCst);self.released.store(heap.1,Ordering::SeqCst);if self.interrupt.swap(false,Ordering::SeqCst){panic!("actual factory recorded its reply before interruption")}result}
 fn recover_retire_owned<'reply>(&self,_:&mut Option<String>,_:&mut RetainedAllocationEffect<'_>,reply:FactoryProducerReply<'reply,dyn ErasedSnapshotRetirement,OriginalRetirementFailure>)->FactoryProducerReplyComplete<'reply,OriginalRetirementFailure>{self.recoveries.fetch_add(1,Ordering::SeqCst);reply.pending()}
}
struct BorrowedFactoryClose;
