 fn close_state_preparation_work_demand(&self,_:&bool,_:usize)->Result<u64,ValueError>{Ok(1)}
 fn prepare_close_state_step(&self,_:&mut bool,_:&mut RetainedAllocationEffect<'_>)->RetainedWorkPoll{RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"fixture requires its borrowed preparation")),work:0})}
