 fn close_state_preparation_is_complete(state:&bool)->bool{*state}
 fn transfer_payload(_:Self,_:&mut bool){}
 fn close_state_demands(_:&bool,_:usize)->Result<RetirementDemand,ValueError>{Ok(Default::default())}
