#[test]
fn nested_factory_recorded_preparation_unwind_recovers_without_replay(){
 use semio_framework_value_control_contract::OriginalEffectAuthority;
 let law:serde_json::Value=serde_json::from_str(include_str!("nested.json")).unwrap();let fixture:serde_json::Value=serde_json::from_str(include_str!("fixture.json")).unwrap();NESTED_PREPARE_CALLS.store(0,Ordering::SeqCst);NESTED_PREPARE_RECOVERS.store(0,Ordering::SeqCst);let mut bank=EffectBank::new(Wallet::from_profile(&fixture["stock"]));
 let(parent,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||{let child:Arc<dyn FactoryRetirement>=Arc::new(InterruptedNestedFactory);Arc::new(BorrowedNestedFactory{child})});let held=bank.loan(1,law["maximumCopyBytes"].as_u64().unwrap()as usize);bank.post(RetainedCloneProgress{retained_capacity_bytes:heap.0,..Default::default()},held,heap);
 let mut cursor=retirement::controlled::ControlledRetirement::retain(FactoryAuthority::new(parent));let mut authority=OriginalEffectAuthority::new(BorrowedFactoryCursor);let mut interrupted=false;
 for _ in 0..law["maximumTurns"].as_u64().unwrap(){if cursor.terminal_is_empty(){break}let d=cursor.next_demand(4096).unwrap();assert!(d.copy_bytes<=4096);let work=cursor.next_computational_work(4096).unwrap();let g=grant(d);let(mut action,mut answer)=(None,None);let mut observed=(0usize,0usize);let mut spent=0u128;let mut had_unwind=false;
  for _ in 0..law["maximumTurns"].as_u64().unwrap(){let(result,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||std::panic::catch_unwind(std::panic::AssertUnwindSafe(||bank.run(g,work,|effect|{let before=effect.performed_work();let ready=authority.drive(&mut &mut cursor,effect,&mut action).unwrap();let work=effect.performed_work()-before;if ready{RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work})}else{RetainedWorkPoll::Pending{work}}}))));match result{Err(_)=>{assert!(!interrupted);interrupted=true;had_unwind=true;assert_eq!(bank.actual(),None);continue},Ok((poll,actual))=>{if let Some(actual)=actual{assert_eq!(actual,heap.0)}observed.0+=heap.0;observed.1+=heap.1;spent+=poll.work();if matches!(poll,RetainedWorkPoll::Complete(_)){assert!(action.as_mut().unwrap().transfer_reply(&mut answer).unwrap());authority.finish(&mut action).unwrap();break}}}}
  let progress=answer.expect("nested original reply").unwrap().progress();assert!(progress.copied_items<=1);let admitted=bank.take_admitted();assert_eq!(admitted,if spent==0&&!had_unwind{None}else{Some(true)});bank.post(progress,g,observed);
 }
 assert!(interrupted);assert!(cursor.terminal_is_empty());assert!(authority.into_producer().is_ok());assert_eq!(NESTED_PREPARE_CALLS.load(Ordering::SeqCst),law["receiveCount"].as_u64().unwrap()as usize);assert_eq!(NESTED_PREPARE_RECOVERS.load(Ordering::SeqCst),law["recoveryCount"].as_u64().unwrap()as usize);
}

static NESTED_PENDING_CALLS:AtomicUsize=AtomicUsize::new(0);
static NESTED_PENDING_RECOVERS:AtomicUsize=AtomicUsize::new(0);
struct PendingNestedFactory;
struct PendingNestedState{prepared:bool,pending:bool}
impl FactoryPayloadRetirement for PendingNestedFactory{
 type CloseState=PendingNestedState;
 fn close_state_birth_bytes(&self)->usize{std::mem::size_of::<PendingNestedState>()}
 fn close_state_constructor_depth(&self)->usize{0}
 fn close_state_constructor_copy_bytes(&self)->usize{std::mem::size_of::<PendingNestedState>()}
 fn prepare_close_state(&self)->PendingNestedState{PendingNestedState{prepared:false,pending:false}}
 fn close_state_preparation_demands(&self,_:&PendingNestedState,_:usize)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:3*std::mem::size_of::<bool>(),depth:1,..Default::default()})}
 fn close_state_preparation_work_demand(&self,_:&PendingNestedState,_:usize)->Result<u64,ValueError>{Ok(2)}
 fn prepare_close_state_step(&self,_:&mut PendingNestedState,_:&mut RetainedAllocationEffect<'_>)->RetainedWorkPoll{RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"fixture requires borrowed preparation")),work:0})}
 fn prepare_close_state_into<'r>(&self,state:&mut PendingNestedState,effect:&mut RetainedAllocationEffect<'_>,reply:semio_framework_value_control_contract::OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<semio_framework_value_control_contract::OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{NESTED_PENDING_CALLS.fetch_add(1,Ordering::SeqCst);assert!(!state.prepared);assert!(effect.performed(1)?);state.prepared=true;state.pending=true;Ok(reply.pending())}
 fn recover_prepare_close_state_into<'r>(&self,state:&mut PendingNestedState,effect:&mut RetainedAllocationEffect<'_>,reply:semio_framework_value_control_contract::OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<semio_framework_value_control_contract::OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{NESTED_PENDING_RECOVERS.fetch_add(1,Ordering::SeqCst);assert!(state.prepared&&state.pending);assert!(effect.performed(1)?);state.pending=false;Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:3*std::mem::size_of::<bool>(),..Default::default()}))))}
 fn close_state_preparation_is_complete(state:&PendingNestedState)->bool{state.prepared}
 fn transfer_payload(_:Self,_:&mut PendingNestedState){}
 fn close_state_demands(_:&PendingNestedState,_:usize)->Result<RetirementDemand,ValueError>{Ok(Default::default())}
 fn close_state_work_demand(_:&PendingNestedState,_:usize)->Result<u64,ValueError>{Ok(0)}
 fn close_state_step(_:&mut PendingNestedState,_:&mut RetainedAllocationEffect<'_>)->OriginalRetirementPoll{RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0})}
 unsafe fn close_state_terminal_native_release_safe()->bool{true}
 fn close_state_terminal_is_empty(state:&PendingNestedState)->bool{state.prepared&&!state.pending}
}
